import{c as a,Q as t,j as n,m as i}from"./chunks/framework.BXc4yaFE.js";const f=JSON.parse('{"title":"AgentDoG 1.5: A Lightweight and Scalable Alignment Framework for AI Agent Safety and Security","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.29801","title":"AgentDoG 1.5: A Lightweight and Scalable Alignment Framework for AI Agent Safety and Security","archived_date":"2026-07-30T00:00:00.000Z","arxiv_id":2605.29801,"authors":["Dongrui Liu","Yu Li","Zhonghao Yang","Peng Wang","Guanxu Chen","Yuejin Xie","Qinghua Mao","Wanying Qu","Yanxu Zhu","Tianyi Zhou"],"collected_at":"2026-07-30T00:00:00.000Z","collected_by":"routine-d","domain":"ai-safety-red-teaming","pdf_path":"pdfs/2605.29801.pdf","published_date":"2026-05-28T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-28-agentdog-lightweight-agent-safety-alignment-2605-29801.md","filePath":"research/papers/2026-05-28-agentdog-lightweight-agent-safety-alignment-2605-29801.md","lastUpdated":1785909234000}'),r={name:"research/papers/2026-05-28-agentdog-lightweight-agent-safety-alignment-2605-29801.md"};function g(o,e,l,d,s,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="agentdog-1-5-a-lightweight-and-scalable-alignment-framework-for-ai-agent-safety-and-security" tabindex="-1">AgentDoG 1.5: A Lightweight and Scalable Alignment Framework for AI Agent Safety and Security <a class="header-anchor" href="#agentdog-1-5-a-lightweight-and-scalable-alignment-framework-for-ai-agent-safety-and-security" aria-label="Permalink to &quot;AgentDoG 1.5: A Lightweight and Scalable Alignment Framework for AI Agent Safety and Security&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>針對 OpenClaw 等開放世界 agent 的安全風險，更新安全 taxonomy 涵蓋新興威脅（含 Codex/OpenClaw 執行環境），並建構資料引擎以極少訓練資料（約 1k 筆樣本）訓練 0.8B–8B 輕量模型變體，效能可比擬 GPT-5.4 等閉源模型。資料引擎採 influence-function purification；建立 agentic safety 訓練環境，將 Docker 層部署開銷降低兩個數量級。AgentDoG 1.5 可作為訓練期外部署的 training-free 即時 guardrail，於多樣複雜互動式 agentic 場景展現穩定表現；模型與資料集皆公開釋出。</p><h2 id="與-harness-的關聯" tabindex="-1">與 Harness 的關聯 <a class="header-anchor" href="#與-harness-的關聯" aria-label="Permalink to &quot;與 Harness 的關聯&quot;">​</a></h2><p>輕量、可即時掛載的 training-free guardrail，是本 workspace core.md「安全例外」條款（加密原語/身份驗證等永遠獨立共用函式）在 agent 安全層的對應實作型態——把安全判斷收斂成可低成本部署的獨立守門模組，而非仰賴主模型自我約束，與 harness-mu（execution hook 非 LLM 治理）方法論同源。</p>',5)])])}const u=a(r,[["render",g]]);export{f as __pageData,u as default};
